switch_zcode() {
  local theme_dir="${XDG_CONFIG_HOME:-$HOME/.config}/zcode"
  local theme_file="$theme_dir/amane.css"
  local scheme="dark"
  [ "${C[light]}" = "true" ] && scheme="light"
  mkdir -p "$theme_dir"

  local theme_tmp
  theme_tmp="$(mktemp "${theme_file}.XXXXXX")" || return 1
  cat > "$theme_tmp" << EOF
/* Auto-generated by switch-theme.sh */
:root, :host, .dark, .theme-zai-dark {
  color-scheme: $scheme !important;
  --color-background: ${C[base]} !important;
  --color-background-alt: color-mix(in oklab, ${C[mantle]} 60%, transparent) !important;
  --color-background-win-alt: ${C[mantle]} !important;
  --color-header: ${C[base]} !important;
  --color-panel: ${C[base]} !important;
  --color-sidebar: ${C[crust]} !important;
  --color-surface: color-mix(in oklab, ${C[text]} 5%, transparent) !important;
  --color-surface-hover: color-mix(in oklab, ${C[text]} 10%, transparent) !important;
  --color-hover: ${C[surface0]} !important;
  --color-selected: ${C[surface0]} !important;
  --color-card: ${C[surface0]} !important;
  --color-card-selected: ${C[surface1]} !important;
  --color-card-border: ${C[surface1]} !important;
  --color-popover: ${C[mantle]} !important;
  --color-popover-foreground: ${C[text]} !important;
  --color-popover-header: ${C[surface0]} !important;
  --color-popover-border: ${C[surface1]} !important;
  --color-menu: ${C[mantle]} !important;
  --color-menu-hover: ${C[surface0]} !important;
  --color-input: ${C[surface0]} !important;
  --color-input-focused: ${C[mantle]} !important;
  --color-input-border: ${C[surface1]} !important;
  --color-input-border-hover: ${C[surface2]} !important;
  --color-input-border-focused: ${C[accent]} !important;
  --color-border: ${C[surface1]} !important;
  --color-border-hover: ${C[surface2]} !important;
  --color-foreground: ${C[text]} !important;
  --color-foreground-subtle: ${C[subtext0]} !important;
  --color-foreground-subtlest: ${C[overlay1]} !important;
  --color-foreground-inverse: ${C[base]} !important;
  --color-primary: ${C[accent]} !important;
  --color-primary-foreground: ${C[base]} !important;
  --color-secondary: ${C[surface1]} !important;
  --color-brand: ${C[accent]} !important;
  --color-accent: color-mix(in oklab, ${C[accent]} 24%, transparent) !important;
  --color-resize-handle: ${C[accent]} !important;
  --color-tab: ${C[mantle]} !important;
  --color-tab-active: ${C[surface0]} !important;
  --color-tab-border: ${C[surface1]} !important;
  --color-toast: ${C[surface0]} !important;
  --color-tooltip: ${C[surface0]} !important;
  --color-tooltip-foreground: ${C[text]} !important;
  --color-tooltip-tag: ${C[surface1]} !important;
  --color-tooltip-tag-foreground: ${C[subtext1]} !important;
  --color-tag: ${C[surface0]} !important;
  --color-markdown-inline-code: ${C[surface0]} !important;
  --color-success: ${C[green]} !important;
  --color-success-foreground: ${C[base]} !important;
  --color-success-surface: color-mix(in oklab, ${C[green]} 18%, transparent) !important;
  --color-success-surface-foreground: ${C[green]} !important;
  --color-warning: ${C[yellow]} !important;
  --color-warning-foreground: ${C[base]} !important;
  --color-warning-surface: color-mix(in oklab, ${C[yellow]} 16%, transparent) !important;
  --color-warning-surface-foreground: ${C[yellow]} !important;
  --color-destructive: ${C[red]} !important;
  --color-destructive-foreground: ${C[base]} !important;
  --color-destructive-surface: color-mix(in oklab, ${C[red]} 16%, transparent) !important;
  --color-destructive-surface-foreground: ${C[red]} !important;
  --color-progress-surface: color-mix(in oklab, ${C[blue]} 18%, transparent) !important;
  --color-progress-surface-foreground: ${C[blue]} !important;
  --color-diff-added: ${C[green]} !important;
  --color-diff-added-foreground: ${C[base]} !important;
  --color-diff-removed: ${C[red]} !important;
  --color-diff-removed-foreground: ${C[base]} !important;
  --color-git-modified: ${C[yellow]} !important;
  --color-git-added: ${C[green]} !important;
  --color-git-deleted: ${C[red]} !important;
  --color-git-renamed: ${C[blue]} !important;
  --color-git-untracked: ${C[green]} !important;
  --color-terminal-bg: ${C[crust]} !important;
  --color-terminal-fg: ${C[text]} !important;
  --color-terminal-cursor: ${C[text]} !important;
  --color-terminal-cursor-accent: ${C[base]} !important;
  --color-terminal-selection: color-mix(in oklab, ${C[accent]} 32%, transparent) !important;
  --color-terminal-selection-inactive: color-mix(in oklab, ${C[accent]} 22%, transparent) !important;
  --color-terminal-black: ${C[surface2]} !important;
  --color-terminal-red: ${C[red]} !important;
  --color-terminal-green: ${C[green]} !important;
  --color-terminal-yellow: ${C[yellow]} !important;
  --color-terminal-blue: ${C[blue]} !important;
  --color-terminal-magenta: ${C[mauve]} !important;
  --color-terminal-cyan: ${C[teal]} !important;
  --color-terminal-white: ${C[subtext1]} !important;
  --color-terminal-bright-black: ${C[overlay1]} !important;
  --color-terminal-bright-red: ${C[red]} !important;
  --color-terminal-bright-green: ${C[green]} !important;
  --color-terminal-bright-yellow: ${C[yellow]} !important;
  --color-terminal-bright-blue: ${C[blue]} !important;
  --color-terminal-bright-magenta: ${C[mauve]} !important;
  --color-terminal-bright-cyan: ${C[teal]} !important;
  --color-terminal-bright-white: ${C[text]} !important;
  --color-sky-50: ${C[blue]} !important;
  --color-sky-100: ${C[blue]} !important;
  --color-sky-200: ${C[blue]} !important;
  --color-sky-300: ${C[blue]} !important;
  --color-sky-400: ${C[accent]} !important;
  --color-sky-500: ${C[accent]} !important;
  --color-sky-600: ${C[blue]} !important;
  --color-sky-700: ${C[blue]} !important;
  --color-sky-900: color-mix(in oklab, ${C[accent]} 35%, ${C[base]}) !important;
  --color-sky-950: color-mix(in oklab, ${C[accent]} 24%, ${C[base]}) !important;
  --color-green-300: ${C[green]} !important;
  --color-green-400: ${C[green]} !important;
  --color-green-500: ${C[green]} !important;
  --color-green-600: ${C[green]} !important;
  --color-red-300: ${C[red]} !important;
  --color-red-400: ${C[red]} !important;
  --color-red-500: ${C[red]} !important;
  --color-red-600: ${C[red]} !important;
  --color-yellow-300: ${C[yellow]} !important;
  --color-yellow-400: ${C[yellow]} !important;
  --color-yellow-500: ${C[yellow]} !important;
  --color-yellow-600: ${C[yellow]} !important;
  --color-violet-300: ${C[mauve]} !important;
  --color-violet-400: ${C[mauve]} !important;
  --color-violet-500: ${C[mauve]} !important;
  --color-violet-600: ${C[mauve]} !important;
  --color-teal-300: ${C[teal]} !important;
  --color-teal-400: ${C[teal]} !important;
  --color-teal-600: ${C[teal]} !important;
}
body, #loading { background: ${C[base]} !important; color: ${C[text]} !important; }
EOF
  mv "$theme_tmp" "$theme_file"
}
